//go:build gcp_parity

package gcpparity

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"sort"
	"strconv"
	"strings"
	"time"
)

// Generated field coverage (FC3).
//
// The catalog in docs/fidelity/field-coverage.csv classifies every field of the
// pilot resources; this file turns those classifications into assertions. The
// data comes from tests/gcpparity/zz_fieldcoverage_generated.go, which is
// generated by tools/fieldgen from the same catalog and the API definitions, so
// the values, the classifications and the scenario cannot drift apart: a new
// `roundtrip` field appears there as a value the resource driver must place, and
// the driver fails the suite until it does.
//
// For every pilot resource the suite drives, per transport:
//
//   - create with every roundtrip field set to a type-driven non-default value;
//   - get: every field is served back with the value that was sent;
//   - cross-transport read: every field the other transport also classifies as
//     roundtrip is served there too (this is the TGM1-3 class);
//   - list: the resource appears in its list;
//   - update, one step per masked field: the new value is served back;
//   - a negative write per output-only field (at create) and immutable field (at
//     update): the value is ignored or the request is INVALID_ARGUMENT;
//   - an absence create: an optional block the caller did not send is not
//     synthesized (or is a documented server default);
//   - delete, then a read that must answer NOT_FOUND.
//
// A finding is either a gate failure or, when it is recorded in
// testdata/fieldcoverage-baseline.json with a written reason and a review date,
// a known gap. A baseline entry that stops failing is stale and gates too, so
// the baseline is a ratchet, not a suppression.

// generatedField is one row of the generated dataset emitted by tools/fieldgen.
type generatedField struct {
	Service     string
	Resource    string
	Transport   string
	Field       string
	Path        string
	Kind        string
	Repeated    bool
	Value       string
	Ref         string
	Update      bool
	UpdateValue string
	Behavior    string
	Coverage    string
}

// generatedWriteAttempt is one generated negative write.
type generatedWriteAttempt struct {
	Service   string
	Resource  string
	Transport string
	Field     string
	Path      string
	Kind      string
	At        string
	Value     string
	Coverage  string
}

// generatedResourceKey is the dataset key for one resource on one transport.
func generatedResourceKey(service, resource, transport string) string {
	return service + "/" + resource + "/" + transport
}

// generatedFieldsFor returns the generated roundtrip values for one resource and
// transport, sorted by path so a parent is placed before its children.
func generatedFieldsFor(service, resource, transport string) []generatedField {
	var out []generatedField
	for _, f := range generatedFieldValues {
		if f.Service == service && f.Resource == resource && f.Transport == transport {
			out = append(out, f)
		}
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].Path != out[j].Path {
			return out[i].Path < out[j].Path
		}
		return out[i].Field < out[j].Field
	})
	return out
}

// generatedAttemptsFor returns the generated negative writes for one resource and
// transport.
func generatedAttemptsFor(service, resource, transport string) []generatedWriteAttempt {
	var out []generatedWriteAttempt
	for _, a := range generatedFieldWriteAttempts {
		if a.Service == service && a.Resource == resource && a.Transport == transport {
			out = append(out, a)
		}
	}
	return out
}

// generatedFieldKeys is the set of catalog rows the generated dataset covers.
func generatedFieldKeys() map[string]bool {
	out := map[string]bool{}
	for _, f := range generatedFieldValues {
		out[f.Service+"/"+f.Transport+"/"+f.Resource+"/"+f.Field] = true
	}
	return out
}

// fieldResource is one pilot resource's wire adapter. The generated dataset
// supplies the values; the adapter supplies the request paths (which no
// definition enumerates).
type fieldResource interface {
	// resourceID is "<service>/<resource>" as the catalog spells it.
	resourceID() string
	transports() []string
	// prepare creates whatever the resource needs before a create (a key ring
	// for a crypto key, a database for a backup schedule) and resolves the
	// generated reference values (a real KMS key, a real Pub/Sub topic).
	prepare(ctx context.Context, e *Env) (map[string]string, error)
	// baseBody is the mandatory scaffolding the resource's API requires and the
	// catalog does not classify as a roundtrip field (a CryptoKey purpose, a
	// bucket name). It is part of the created resource, not of the generated
	// field set.
	baseBody(e *Env, id string) map[string]any
	// absenceBody is the minimal create the absence test sends: the mandatory
	// scaffolding plus any field the API requires but which the generated set
	// does not carry (a Database location). It must omit every optional block.
	absenceBody(e *Env, id string) map[string]any
	// fill places the resource's generated fields for one create phase,
	// including any shape a message-typed leaf needs (the catalog stops at
	// depth 2 for a few).
	fill(b *fieldBody, phase string)
	// deletable reports whether the API has a delete for this resource. A
	// resource whose real API cannot be deleted (a KMS crypto key) skips the
	// delete/NotFound assertions and relies on the ephemeral run state.
	deletable() bool
	// phases names the create phases the resource needs; a resource whose fields
	// are mutually exclusive at create (Cloud DNS forwarding vs peering) returns
	// more than one. The union of phases must place every generated field.
	phases() []string
	create(ctx context.Context, e *Env, transport, id string, body map[string]any) error
	read(ctx context.Context, e *Env, transport, id string) (map[string]any, error)
	listContains(ctx context.Context, e *Env, transport, id string) (bool, error)
	// update applies one masked update. mask is the mask path (no array
	// markers); body is the request body the suite built from the current
	// state, so a leaf inside a nested block sends the whole block.
	update(ctx context.Context, e *Env, transport, id, mask string, body map[string]any) error
	delete(ctx context.Context, e *Env, transport, id string) error
}

// fieldBody accumulates a create body while tracking which generated fields it
// placed, so an unplaced field (a new catalog row with no scenario) is a test
// failure rather than a silent omission.
type fieldBody struct {
	service   string
	resource  string
	transport string
	fields    []generatedField
	refs      map[string]string
	body      map[string]any
	used      map[string]bool
	skipped   map[string]string
	placeErr  error
}

func newFieldBody(service, resource, transport string, refs map[string]string) *fieldBody {
	return &fieldBody{
		service:   service,
		resource:  resource,
		transport: transport,
		fields:    generatedFieldsFor(service, resource, transport),
		refs:      refs,
		body:      map[string]any{},
		used:      map[string]bool{},
		skipped:   map[string]string{},
	}
}

// place marks a generated field used and writes its create value at its path.
func (b *fieldBody) place(field string) error { return b.placeAt(field, 0) }

// placeAt is place for a field under a repeated ancestor, writing it into the
// instance at idx (a repeated message with a oneof needs one element per
// variant, not every variant in one element).
func (b *fieldBody) placeAt(field string, idx int) error {
	f, ok := b.field(field)
	if !ok {
		return fmt.Errorf("%s/%s/%s: generated field %q does not exist (was it removed from the catalog without regenerating?)", b.service, b.resource, b.transport, field)
	}
	if f.Kind == "message" {
		b.used[field] = true
		return nil
	}
	var value any
	if f.Ref != "" {
		v, ok := b.refs[f.Ref]
		if !ok {
			return fmt.Errorf("%s: reference %q was not resolved by the resource prelude", field, f.Ref)
		}
		value = v
	} else {
		if err := json.Unmarshal([]byte(f.Value), &value); err != nil {
			return fmt.Errorf("%s: generated value %q is not JSON: %w", field, f.Value, err)
		}
	}
	b.used[field] = true
	return insertPath(b.body, f.Path, value, idx)
}

// placeAll places every scalar/map/enum field at its default instance. A driver
// with a repeated oneof message calls placeAt itself instead.
func (b *fieldBody) placeAll() error {
	for _, f := range b.fields {
		if f.Kind == "message" {
			continue
		}
		if err := b.placeAt(f.Field, 0); err != nil {
			return err
		}
	}
	return nil
}

// placePrefix places every field under prefix (a phase that carries only one
// mutually-exclusive block).
func (b *fieldBody) placePrefix(prefix string) {
	for _, f := range b.fields {
		if f.Kind == "message" || b.used[f.Field] {
			continue
		}
		if f.Path == prefix || strings.HasPrefix(f.Path, prefix+"[") || strings.HasPrefix(f.Path, prefix+".") {
			if err := b.placeAt(f.Field, 0); err != nil && b.placeErr == nil {
				b.placeErr = err
			}
		}
	}
}

// placeOutside places every field that does not live under prefix. A driver
// that lays out one block itself (a repeated oneof) uses it for the rest.
func (b *fieldBody) placeOutside(prefix string) {
	for _, f := range b.fields {
		if f.Kind == "message" || b.used[f.Field] {
			continue
		}
		if f.Path == prefix || strings.HasPrefix(f.Path, prefix+"[") || strings.HasPrefix(f.Path, prefix+".") {
			continue
		}
		if err := b.placeAt(f.Field, 0); err != nil && b.placeErr == nil {
			b.placeErr = err
		}
	}
}

// shape places a message-typed field the catalog stops at (depth 2) with the
// sub-fields the API requires, and marks it used.
func (b *fieldBody) shape(field string, value map[string]any) error {
	f, ok := b.field(field)
	if !ok {
		return fmt.Errorf("%s: shape for unknown generated field %q", b.resource, field)
	}
	b.used[field] = true
	return insertPath(b.body, f.Path, value, 0)
}

// shapeValue is shape for a message whose value is an array (a repeated nested
// message).
func (b *fieldBody) shapeValue(field string, value any) error {
	f, ok := b.field(field)
	if !ok {
		return fmt.Errorf("%s: shape for unknown generated field %q", b.resource, field)
	}
	b.used[field] = true
	return insertPath(b.body, f.Path, value, 0)
}

// shapeAt is shape for a field under a repeated ancestor.
func (b *fieldBody) shapeAt(field string, idx int, value map[string]any) error {
	f, ok := b.field(field)
	if !ok {
		return fmt.Errorf("%s: shape for unknown generated field %q", b.resource, field)
	}
	b.used[field] = true
	return insertPath(b.body, f.Path, value, idx)
}

// skip records that a generated field is deliberately not driven, with a reason.
// The reason is surfaced as a finding so it must be baselined.
func (b *fieldBody) skip(field, reason string) {
	b.used[field] = true
	b.skipped[field] = reason
}

func (b *fieldBody) field(name string) (generatedField, bool) {
	for _, f := range b.fields {
		if f.Field == name {
			return f, true
		}
	}
	return generatedField{}, false
}

// uncovered lists generated fields the driver never placed. A message row is
// covered when a descendant was placed (or the driver shaped it).
func (b *fieldBody) uncovered() []string {
	var out []string
	for _, f := range b.fields {
		if b.used[f.Field] {
			continue
		}
		if f.Kind == "message" && b.hasDescendantPlaced(f.Path) {
			continue
		}
		out = append(out, f.Field)
	}
	return out
}

func (b *fieldBody) hasDescendantPlaced(path string) bool {
	for field := range b.used {
		f, ok := b.field(field)
		if !ok {
			continue
		}
		if strings.HasPrefix(f.Path, path+".") || strings.HasPrefix(f.Path, path+"[") {
			return true
		}
	}
	return false
}

// wantValue decodes the value the driver sent for a generated field.
func (b *fieldBody) wantValue(f generatedField) any {
	if f.Ref != "" {
		return b.refs[f.Ref]
	}
	var v any
	_ = json.Unmarshal([]byte(f.Value), &v)
	return v
}

// wantJSON renders the sent value for a finding message.
func (b *fieldBody) wantJSON(f generatedField) string {
	if f.Ref != "" {
		return b.refs[f.Ref]
	}
	return f.Value
}

// skippedFindings returns one finding per deliberately skipped field.
func (b *fieldBody) skippedFindings() []fieldFinding {
	var out []fieldFinding
	for field, reason := range b.skipped {
		out = append(out, fieldFinding{resource: b.resource, transport: b.transport, band: bandNotDrivable, field: field, detail: reason})
	}
	sort.Slice(out, func(i, j int) bool { return out[i].field < out[j].field })
	return out
}

// insertPath writes value at a generated path. Segments ending in `[]` descend
// into (and create) an array with at least idx+1 elements.
func insertPath(root map[string]any, path string, value any, idx int) error {
	segs := strings.Split(path, ".")
	cur := root
	for i, seg := range segs {
		repeated := strings.HasSuffix(seg, "[]")
		name := strings.TrimSuffix(seg, "[]")
		last := i == len(segs)-1
		if last {
			if repeated {
				// The leaf value itself is the array/object (a repeated
				// scalar or a map).
				cur[name] = value
				return nil
			}
			cur[name] = value
			return nil
		}
		if !repeated {
			child, ok := cur[name].(map[string]any)
			if !ok {
				child = map[string]any{}
				cur[name] = child
			}
			cur = child
			continue
		}
		// Repeated ancestor: materialise an array of maps and descend into
		// element idx.
		arr, ok := cur[name].([]any)
		if !ok {
			arr = []any{}
		}
		for len(arr) <= idx {
			arr = append(arr, map[string]any{})
		}
		child, ok := arr[idx].(map[string]any)
		if !ok {
			child = map[string]any{}
			arr[idx] = child
		}
		cur[name] = arr
		cur = child
	}
	return nil
}

// lookupPath reads a value out of a decoded response body at a generated path.
// A repeated ancestor requires every element to carry the leaf (an assertion on
// the whole array), returning the first element's value for comparison.
func lookupPath(body map[string]any, path string) (any, bool) {
	return lookupSegs(body, strings.Split(path, "."))
}

// lookupSegs walks the path segments. A `[]` suffix descends into every element
// of an array (which may itself sit inside another array, e.g.
// secretVolumes[].versions[].path), so a nested repeated message is asserted on
// every element rather than being unreadable.
func lookupSegs(cur any, segs []string) (any, bool) {
	if len(segs) == 0 {
		return cur, true
	}
	m, ok := cur.(map[string]any)
	if !ok {
		return nil, false
	}
	seg := segs[0]
	repeated := strings.HasSuffix(seg, "[]")
	v, ok := m[strings.TrimSuffix(seg, "[]")]
	if !ok {
		return nil, false
	}
	if !repeated {
		return lookupSegs(v, segs[1:])
	}
	arr, ok := v.([]any)
	if !ok || len(arr) == 0 {
		return nil, false
	}
	var first any
	for j, el := range arr {
		got, ok := lookupSegs(el, segs[1:])
		if !ok {
			return nil, false
		}
		if j == 0 {
			first = got
		}
	}
	return first, true
}

// equalField compares a sent value with a served one. It folds the encodings the
// two transports legitimately differ in (protojson renders int64 as a string,
// Discovery JSON as a number) and sorts nothing: an array's order is part of the
// value here because the caller sent it in that order.
func equalField(want, got any) bool {
	if wn, ok := numberValue(want); ok {
		if gn, ok := numberValue(got); ok {
			return wn == gn
		}
		return false
	}
	if ws, ok := want.(string); ok {
		// Durations are rendered "3600s" by both transports; timestamps may
		// round-trip through RFC3339 with a different precision.
		if gs, ok := got.(string); ok {
			if ws == gs {
				return true
			}
			if normalizeTimestamp(ws) != "" && normalizeTimestamp(ws) == normalizeTimestamp(gs) {
				return true
			}
			return false
		}
		return false
	}
	// Arrays and maps: compare canonical JSON.
	w, errW := json.Marshal(want)
	g, errG := json.Marshal(got)
	if errW != nil || errG != nil {
		return false
	}
	if string(w) == string(g) {
		return true
	}
	// A repeated ancestor's value is compared element-wise by the caller; for a
	// whole array the element order is significant, so a sorted fallback would
	// hide a reorder. Compare canonical forms only.
	return false
}

func numberValue(v any) (float64, bool) {
	switch t := v.(type) {
	case float64:
		return t, true
	case float32:
		return float64(t), true
	case int:
		return float64(t), true
	case int64:
		return float64(t), true
	case json.Number:
		f, err := t.Float64()
		return f, err == nil
	case string:
		// protojson int64 strings ("47") compare with REST numbers.
		if t == "" {
			return 0, false
		}
		f, err := strconv.ParseFloat(t, 64)
		if err != nil {
			return 0, false
		}
		return f, true
	}
	return 0, false
}

// normalizeTimestamp reduces an RFC3339 timestamp to its UTC instant so a
// transport that renders a different fractional precision still compares equal.
func normalizeTimestamp(s string) string {
	if len(s) < 20 || s[4] != '-' || s[10] != 'T' {
		return ""
	}
	t, err := time.Parse(time.RFC3339Nano, s)
	if err != nil {
		return ""
	}
	return t.UTC().Format(time.RFC3339Nano)
}

// fieldFinding is one assertion the suite could not satisfy.
type fieldFinding struct {
	resource  string
	transport string
	band      string
	field     string
	detail    string
}

const (
	// bandServe: the field was sent but not served back with the same value.
	bandServe = "serve"
	// bandCrossTransport: the field is roundtrip on both transports but the
	// other transport does not serve the value this one accepted.
	bandCrossTransport = "cross-transport"
	// bandUpdate: a one-field masked update was not honoured.
	bandUpdate = "update"
	// bandNegativeWrite: an output-only/immutable write was not ignored or
	// rejected.
	bandNegativeWrite = "negative-write"
	// bandAbsence: an optional block was synthesized by a create that omitted it.
	bandAbsence = "absence"
	// bandNotDrivable: a generated field has no wire adaptation.
	bandNotDrivable = "not-drivable"
	// bandLifecycle: create/list/delete did not behave.
	bandLifecycle = "lifecycle"
)

func (f fieldFinding) key() string {
	field := f.field
	if field == "" {
		field = "*"
	}
	return strings.Join([]string{f.resource, f.transport, f.band, field}, "/")
}

func (f fieldFinding) String() string {
	return fmt.Sprintf("%s [%s] %s: %s", f.resource, f.transport, f.band, f.detail)
}

// fieldBaselineEntry records a known, reviewed gap.
type fieldBaselineEntry struct {
	Resource  string `json:"resource"`
	Transport string `json:"transport"`
	Band      string `json:"band"`
	Field     string `json:"field"`
	Reason    string `json:"reason"`
	ID        string `json:"id"`
	ReviewBy  string `json:"review_by"`
}

func (b fieldBaselineEntry) key() string {
	field := b.Field
	if field == "" {
		field = "*"
	}
	return strings.Join([]string{b.Resource, b.Transport, b.Band, field}, "/")
}

type fieldBaselineFile struct {
	Comment string               `json:"_comment"`
	Entries []fieldBaselineEntry `json:"entries"`
}

// loadFieldBaseline reads the committed baseline.
func loadFieldBaseline(path string) (map[string]fieldBaselineEntry, error) {
	raw, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("read fieldcoverage baseline: %w", err)
	}
	var f fieldBaselineFile
	if err := json.Unmarshal(raw, &f); err != nil {
		return nil, fmt.Errorf("parse %s: %w", path, err)
	}
	out := map[string]fieldBaselineEntry{}
	for i, e := range f.Entries {
		if e.Resource == "" || e.Transport == "" || e.Band == "" || e.Reason == "" || e.ReviewBy == "" || e.ID == "" {
			return nil, fmt.Errorf("%s: entry %d needs resource, transport, band, reason, id and review_by", path, i+1)
		}
		if _, dup := out[e.key()]; dup {
			return nil, fmt.Errorf("%s: duplicate entry %s", path, e.key())
		}
		out[e.key()] = e
	}
	return out, nil
}

// applyFieldBaseline splits findings into gate failures and accepted gaps, and
// reports baseline entries that no longer fail.
func applyFieldBaseline(findings []fieldFinding, baseline map[string]fieldBaselineEntry) (gate []fieldFinding, accepted int, stale []string) {
	hit := map[string]bool{}
	for _, f := range findings {
		if _, ok := baseline[f.key()]; ok {
			hit[f.key()] = true
			accepted++
			continue
		}
		gate = append(gate, f)
	}
	for k := range baseline {
		if !hit[k] {
			stale = append(stale, k)
		}
	}
	sort.Strings(stale)
	return gate, accepted, stale
}
